  @Override
  public AccountMeta[] parseAccounts(final AddressLookupTable lookupTable) {
    return isLegacy() || lookupTable == null
        ? parseAccounts()
        : parseAccounts(Map.of(lookupTable.address(), lookupTable));
  }
